<template>
    <div
        :id="options.id"
        class="home-panel-container"
    >
        <ul class="home-panel">
            <li
                class="home-panel-li"
                :class="pageClass(index)"
                v-for="(items, index) in panelList"
                :key="'page_'+index"
            >
                <div
                    v-for="item in items"
                    class="panel-item"
                    :key="item.menuId"
                    :title="item.modelName"
                    @click="panelHandle(item)"
                >
                    <span class="mark">{{item.qty}}</span>
                    <img
                        v-if="(item.ext$ && item.ext$.todoiconurl)"
                        class="img"
                        :src="item.ext$.todoiconurl"
                    />
                    <p class="text">{{item.modelName}}</p>
                </div>
                <!-- 最后一页-占空dom-解决布局问题 -->
                <template v-if="pageSize !== items.length">
                    <div
                        class="empty-panel-item"
                        v-for="i in pageSize - items.length"
                        :key="'empty_'+i"
                    ></div>
                </template>
            </li>
        </ul>
        <div v-if="panelList.length > 1" class="last-page" @click="changePage(-1)">
            <lastPageImg v-bind="{color: '#999',width:'14px',height:'14px'}" />
        </div>
        <div v-if="panelList.length > 1" class="next-page" @click="changePage(1)">
            <nextPageImg v-bind="{color: '#999',width:'14px',height:'14px'}" />
        </div>
        <!-- Pager分页器 -->
        <ul v-if="panelList.length > 1" class="pager">
            <li
                :class="{active:index === activeIndex}"
                v-for="(i,index) in panelList.length"
                @mouseenter="activePage(index)"
                :key="'_'+index"
            ></li>
        </ul>
    </div>
</template>
<script>
import Gikam from "../../../../core/gikam-core";
export default {
    name: "todoPanel",

    props: {
        options: Object
    },

    data() {
        return {
            panelList: [], // 列表数据-二维数组
            activeIndex: 0, // 选中页
            pageSize: void 0 // 每页的图标数量
        };
    },

    watch: {
        "options.data": {
            handler(data) {
                this.iconsNum(data);
            },
            deep: true
        }
    },

    methods: {
        // 每页的class
        pageClass(index) {
            let className = void 0;
            this.activeIndex - 1 === index && (className = "last-active");
            this.activeIndex === index && (className = "active");
            this.activeIndex + 1 === index && (className = "next-active");
            return className;
        },

        // 判断一页放几个图标
        iconsNum(data) {
            // 容器宽高
            let w = this.options.width;
            let h = this.options.height;
            // 排
            let row = Math.floor(h / (116 + 4));
            row === 0 && (row = 1);
            // 列
            let col = Math.floor((w - 18 * 2) / (125 + 4));
            col === 0 && (col = 1);
            this.pageSize = row * col;
            this.splitList(data, this.pageSize);
        },

        // 数组分页
        splitList(data, num) {
            // 声明数组
            const iconsArr = [];
            data.forEach((item, index) => {
                // 计算该元素为第几个素组内
                const page = Math.floor(index / num);
                // 判断是否存在
                if (!iconsArr[page]) {
                    iconsArr[page] = [];
                }
                iconsArr[page].push(item);
            });
            this.panelList = iconsArr;
        },

        // 换页
        changePage(page) {
            this.activeIndex += page;
            if (this.activeIndex > this.panelList.length - 1) {
                this.activeIndex = this.panelList.length - 1;
            }
            if (this.activeIndex < 0) {
                this.activeIndex = 0;
            }
        },

        // 图标点击事件
        panelHandle(item) {
            if (this.options.onClick) {
                this.options.onClick(item);
            }
        },

        // 分页器
        activePage(index) {
            this.activeIndex = index;
        }
    },

    mounted() {
        this.iconsNum(this.options.data);
        // 窗口改变事件
        Gikam.jQuery(window).resize(() => {
            this.activeIndex = 0;
            this.pageSize = void 0;
            this.iconsNum(this.options.data);
        });
        this.$emit("mounted");
    }
};
</script>
<style>
.home-panel-container {
    width: 100%;
    height: 100%;
    border-radius: 4px;
    position: relative;
}
.home-panel-container .home-panel {
    list-style: none;
    width: 100%;
    height: 100%;
    padding: 0;
    margin: 0;
    overflow: hidden;
    position: relative;
}

.home-panel-container .home-panel .home-panel-li {
    width: 100%;
    height: 100%;
    padding: 18px;
    background-color: #fff;
    position: absolute;
    top: 0;
    left: 100%;
    transition: left 0.5s;
    display: flex;
    flex-wrap: wrap;
    flex-direction: row;
    justify-content: space-around;
    align-content: space-around;
}

.home-panel-container .home-panel .home-panel-li.last-active {
    position: absolute;
    top: 0;
    left: -100%;
}

.home-panel-container .home-panel .home-panel-li.active {
    position: absolute;
    top: 0;
    left: 0;
    transition: left 0.5s;
    z-index: 1;
}

.home-panel-container .home-panel .panel-item {
    width: 125px;
    height: 116px;
    margin: 2px;
    border-radius: 4px;
    position: relative;
}

.home-panel-container .home-panel .empty-panel-item {
    width: 125px;
    height: 116px;
    margin: 2px;
}

.home-panel-container .home-panel .panel-item:hover {
    background-color: #eee;
    cursor: pointer;
}

.home-panel-container .home-panel .panel-item > .mark {
    font-size: 12px;
    line-height: 14px;
    color: #fff;
    padding: 0 6px;
    background-color: #FF003C;
    border-radius: 7px;
    position: absolute;
    top: 8px;
    right: 8px;
}

.home-panel-container .home-panel .panel-item > .img {
    max-width: 50px;
    position: absolute;
    top: 28px;
    right: 0;
    bottom: 0;
    left: 0;
    margin: 0 auto;
}

.home-panel-container .home-panel .panel-item > .text {
    width: 100%;
    font-size: 12px;
    line-height: 12px;
    color: rgba(0, 0, 0, 0.65);
    margin: 0;
    padding: 0 8px;
    text-align: center;
    position: absolute;
    left: 0;
    bottom: 8px;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
}

.home-panel-container .last-page,
.home-panel-container .next-page {
    width: 24px;
    height: 48px;
    background-color: rgba(0, 0, 0, 0.1);
    position: absolute;
    top: 50%;
    margin-top: -12px;
    display: flex;
    justify-content: center;
    align-items: center;
    cursor: pointer;
}

.home-panel-container .last-page {
    left: 0;
    border-radius: 0 2px 2px 0;
    z-index: 2;
}

.home-panel-container .next-page {
    right: 0;
    border-radius: 2px 0 0 2px;
    z-index: 2;
}

.home-panel-container .pager {
    list-style: none;
    height: 16px;
    padding: 0;
    margin: 0;
    position: absolute;
    top: 0;
    right: 16px;
    z-index: 2;
}

.home-panel-container .pager li {
    display: inline-block;
    width: 6px;
    height: 6px;
    margin: 0 3px;
    border-radius: 50%;
    background-color: #eee;
}

.home-panel-container .pager li.active {
    background-color: #999;
    cursor: pointer;
}
</style>